return ['domain'=>NULL,'plural-forms'=>'nplurals=6; plural=(n == 0) ? 0 : ((n == 1) ? 1 : ((n == 2) ? 2 : ((n % 100 >= 3 && n % 100 <= 10) ? 3 : ((n % 100 >= 11 && n % 100 <= 99) ? 4 : 5))));','language'=>'ar','project-id-version'=>'Babilim 1.1.0','pot-creation-date'=>'2026-11-01T01:08:35+00:00','po-revision-date'=>'2026-11-01T01:08:35+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'يُكمل الترجمات الناقصة للإضافات والقوالب المثبّتة بالفعل على موقعك.','Translations'=>'الترجمات','Babilim Settings'=>'إعدادات Babilim','Settings'=>'الإعدادات','You are not allowed to do this.'=>'غير مسموح لك بالقيام بذلك.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'حدّد عددًا أقل من المكوّنات: بحد أقصى %1$d عمليات في كل تشغيل (لقد حدّدت %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'هذا المكوّن غير مثبّت على هذا الموقع، لذا لا يمكن طلب ترجمة له.','Already installed.'=>'مثبّت بالفعل.','Downloaded and installed.'=>'تم التنزيل والتثبيت.','Babilim has not been enabled for this site yet.'=>'لم يتم تفعيل Babilim لهذا الموقع بعد.','No build is available to download for this locale.'=>'لا يتوفر إصدار بناء للتنزيل لهذه اللغة.','Rolled back to the previous build.'=>'تمت العودة إلى إصدار البناء السابق.','Rolled back and reported.'=>'تمت العودة إلى الإصدار السابق وإرسال البلاغ.','Rolled back, but the report could not be sent: %s'=>'تمت العودة إلى الإصدار السابق، لكن تعذّر إرسال البلاغ: %s','Removed.'=>'تمت الإزالة.','Translation requested.'=>'تم طلب الترجمة.','This component was already uploaded. Babilim is checking it now.'=>'تم رفع هذا المكوّن بالفعل. يقوم Babilim بفحصه الآن.','Upload cancelled.'=>'تم إلغاء الرفع.','Upload complete — translation requested.'=>'اكتمل الرفع — تم طلب الترجمة.','This component does not declare a version number, so a translation cannot be requested for it.'=>'لا يُصرّح